def dec(s,scale=1000):
 b=base64.b64decode(s);p=0;sh=0;v=0;out=[]
 for x in b:
  p|=(x&127)<<sh
  if x&128:sh+=7
  else:
   dv=-((p+1)//2) if p&1 else p//2
   v+=dv;out.append(v/scale);p=0;sh=0
 if sh:raise ValueError('invalid encoding')
 return np.array(out)

def load():
 days=dec(DATA['days'],1)
 idx=pd.to_datetime(days.astype(int),unit='D')
 f=pd.DataFrame({key:dec(value) for key,value in DATA.items() if key!='days'},index=idx)
 if len(f)!=213 or any(len(f[key])!=len(f) for key in f.columns):raise ValueError('bad source rows')
 assert f.index[0]==pd.Timestamp('2026-01-05') and f.index[-1]==pd.Timestamp('2026-11-20')
 assert abs(f.tech_close.iloc[-1]-2.230)<1e-7 and abs(f.red_close.iloc[-1]-1.368)<1e-7
 return f
